mapper.select:
SELECT id, session_id, user_id, role, content, tool_name, tool_payload,
       token_count, status, create_time
FROM agent_message
WHERE session_id = #{sessionId}
  AND user_id = #{userId}
  AND status = 1
ORDER BY id DESC
LIMIT #{limit}

mapper.update:
UPDATE agent_message
SET status = 0
WHERE session_id = #{sessionId}
  AND user_id = #{userId}
